<?php
namespace App\Http\Controllers\Api\V1\Crm;
use App\Http\Controllers\Controller;
use App\Models\{Lead,Produto};
use Illuminate\Http\{JsonResponse,Request};
use Illuminate\Support\Facades\DB;
class CrmManagementController extends Controller {
 public function index(Request $r):JsonResponse{$this->authorize('crm.view');$e=$r->user()->empresa_id;$this->defaults($e);$start=now()->startOfMonth();$end=now()->endOfMonth();$won=Lead::where('status','ganho')->whereBetween('fechado_em',[$start,$end]);$open=Lead::where('status','aberto');$users=DB::table('usuarios as u')->leftJoin('leads as l',function($j)use($start,$end){$j->on('l.responsavel_id','=','u.id')->whereBetween('l.created_at',[$start,$end]);})->where('u.empresa_id',$e)->where('u.ativo',true)->groupBy('u.id','u.nome')->selectRaw("u.id,u.nome,COUNT(l.id) leads,SUM(CASE WHEN l.status='ganho' THEN 1 ELSE 0 END) ganhos,COALESCE(SUM(CASE WHEN l.status='ganho' THEN l.valor_estimado ELSE 0 END),0) valor_ganho")->get();return response()->json(['motivos_perda'=>DB::table('crm_motivos_perda')->where('empresa_id',$e)->where('ativo',true)->orderBy('nome')->get(),'automacoes'=>DB::table('crm_automacoes')->where('empresa_id',$e)->orderBy('id')->get(),'metas'=>DB::table('crm_metas')->where('empresa_id',$e)->whereDate('periodo_fim','>=',$start)->orderBy('periodo_inicio')->get(),'produtividade'=>$users,'forecast'=>['pipeline'=>(float)(clone $open)->sum('valor_estimado'),'ponderado'=>(float)(clone $open)->selectRaw('COALESCE(SUM(valor_estimado*probabilidade/100),0) total')->value('total'),'ganho_mes'=>(float)(clone $won)->sum('valor_estimado'),'negocios_ganhos'=>(clone $won)->count()] ]);}
 public function saveReason(Request $r,?int $id=null):JsonResponse{$this->authorize('crm.edit');$d=$r->validate(['nome'=>'required|string|max:150','ativo'=>'boolean']);$e=$r->user()->empresa_id;if($id)DB::table('crm_motivos_perda')->where('empresa_id',$e)->where('id',$id)->update($d+['updated_at'=>now()]);else DB::table('crm_motivos_perda')->insert($d+['empresa_id'=>$e,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Motivo de perda salvo.']);}
 public function saveAutomation(Request $r,?int $id=null):JsonResponse{$this->authorize('crm.edit');$d=$r->validate(['nome'=>'required|string|max:180','gatilho'=>'required|in:lead_criado,etapa_alterada,lead_ganho,lead_perdido','acao'=>'required|in:criar_tarefa','titulo_tarefa'=>'required|string|max:180','dias'=>'required|integer|min:0|max:365','ativo'=>'boolean']);$e=$r->user()->empresa_id;$payload=['nome'=>$d['nome'],'gatilho'=>$d['gatilho'],'acao'=>$d['acao'],'configuracao'=>json_encode(['titulo'=>$d['titulo_tarefa'],'dias'=>$d['dias']]),'ativo'=>$d['ativo']??true,'updated_at'=>now()];if($id)DB::table('crm_automacoes')->where('empresa_id',$e)->where('id',$id)->update($payload);else DB::table('crm_automacoes')->insert($payload+['empresa_id'=>$e,'created_at'=>now()]);return response()->json(['message'=>'Automação salva.']);}
 public function saveGoal(Request $r):JsonResponse{$this->authorize('crm.edit');$d=$r->validate(['usuario_id'=>'nullable|exists:usuarios,id','periodo_inicio'=>'required|date','periodo_fim'=>'required|date|after_or_equal:periodo_inicio','meta_valor'=>'required|numeric|min:0','meta_quantidade'=>'required|integer|min:0']);$d['empresa_id']=$r->user()->empresa_id;$d['created_at']=now();$d['updated_at']=now();DB::table('crm_metas')->insert($d);return response()->json(['message'=>'Meta comercial criada.']);}
 public function products(Request $r,int $id):JsonResponse{$this->authorize('crm.view');$lead=Lead::findOrFail($id);return response()->json(DB::table('crm_oportunidade_produtos')->where('lead_id',$lead->id)->orderBy('id')->get());}
 public function addProduct(Request $r,int $id):JsonResponse{$this->authorize('crm.edit');$lead=Lead::findOrFail($id);$d=$r->validate(['produto_id'=>'nullable|exists:produtos,id','descricao'=>'required|string|max:255','quantidade'=>'required|numeric|min:0.001','valor_unitario'=>'required|numeric|min:0','desconto'=>'nullable|numeric|min:0']);$d['desconto']=$d['desconto']??0;$d['total']=max(0,$d['quantidade']*$d['valor_unitario']-$d['desconto']);$d+=['empresa_id'=>$lead->empresa_id,'lead_id'=>$lead->id,'created_at'=>now(),'updated_at'=>now()];DB::table('crm_oportunidade_produtos')->insert($d);$total=DB::table('crm_oportunidade_produtos')->where('lead_id',$lead->id)->sum('total');$lead->update(['valor_estimado'=>$total]);return response()->json(['message'=>'Item adicionado à oportunidade.','total'=>$total],201);}
 public function catalog(Request $r):JsonResponse{$this->authorize('crm.view');$q=Produto::ativos()->select('id','nome','codigo','preco_venda')->orderBy('nome')->limit(100);if($r->filled('busca'))$q->busca($r->busca);return response()->json($q->get());}
 private function defaults(int $e):void{foreach(['Preço','Concorrência','Sem orçamento','Sem retorno','Prazo adiado','Fora do perfil'] as $name)DB::table('crm_motivos_perda')->updateOrInsert(['empresa_id'=>$e,'nome'=>$name],['ativo'=>true,'updated_at'=>now(),'created_at'=>now()]);}
}
